@module sonority  src=sonority.lua  loc=934  mode=namespace  self=sonority

# Invariants & contracts
  @invariant  pure module: no state; ratios/cents are tuning.lua's, the placement carries them  @ 4
  @invariant  convex in the displacements, so the sweep order and the start buy speed, not the answer  @ 380
  @contract  spellings, window, strength, stiffness, start (per strand), free (strands that sweep)  @ 381
  @contract  → displacements minimising sonority.springCost, the held strands standing at their start  @ 382
  @contract  each swept displacement inside its own strand's window  @ 383
  @invariant  a round decides one slot, so the states it cuts between have placed equally many  @ 502
  @invariant  the first member to place anchors and those before it wait, so one anchor spells each  @ 503
  @invariant  every state ties every member it places; an untied one states nothing, charges none  @ 504
  @invariant  the reach is read against the spelling's own offset, not which member anchors  @ 505
  @contract  members; seat/window/mayWait per strand; moves, width, stiffness → Spellings, best first  @ 619
  @contract  a join is one move; one offset of the spelling seats every member inside its own window  @ 620
  @contract  the width is a width per waiting count; math.huge enumerates the spellings whole  @ 621
  @contract  a sonority no chain reaches and no wait defers has no spelling: the list is empty  @ 622
  @contract  onsets, a spelling list per onset, seat and window per strand, strength, stiffness, cap  @ 860
  @contract  → the cheapest Answer, every answer carried extended by every spelling of the onset  @ 861
  @contract  the strands the onset sounds relax; the rest of an answer stands at the cents it carries  @ 862
  @contract  a sonority holding a waiter is charged in its own onset's slot, as its members place  @ 863
  @contract  answers agreeing to half a cent ahead and owing the same merge; the set is cut to cap  @ 864
  @contract  the cut runs over two pools, the answers that owe and the answers that have paid  @ 865
  @contract  nil where an onset has no spelling — a sonority the target can't reach refuses it  @ 866

# Shapes
  @shape  Coords = {[oddPrime]=exponent}; prime 2 is absent, so the score reads harmony not spacing  @ 5
  @shape  Strand = { notes={ {ppq,pitch,endppq,..},.. }, class=<step-class>, shortlist={ Candidate,.. } }; the walk reads the strikes, the releases and the class  @ 6
  @shape  Sonority = { ppq, strands={ strandIndex,.. } }; most recently struck first, the last n struck and whatever else still sounds  @ 7
  @shape  Candidate = { coords=Coords, strain=<distance from the written step, in half-windows> }  @ 8
  @shape  Spring = { i=<strand>, j=<strand>, delta=<cents> }; the pair is pure where d[j] - d[i] = delta  @ 302
  @shape  Window = { below=<cents to the step below>, above=<cents to the step above> }  @ 327
  @shape  State = { at={ [slot]=Placed }, components={ {slot,..},.. }, parts, key, waits, score, lo/hi=<the offsets left open> }  @ 470
  @shape  Placed = { coords=Coords, cents=<the pure position>, deviation=<from the seat>, component }  @ 471
  @shape  Spelling = { box=<what its components carry>, springs={Spring,..}, waiting={member,..}, placed={ [strand]={ coords=Coords, component } } }  @ 618
  @shape  Onset = { ppq, members={strand,..}, sounding={strand,..}, mayWait={[strand]=true,..} }  @ 655
  @shape  Answer = { choice={ spelling per onset }, springs={ Spring list per onset }, box, displacement, cost, held={ [onset]=Held } }  @ 858
  @shape  Held = { placed={ [strand]={ coords=Coords, component } }, waiting={ [strand]=true }, box=<charged so far> }  @ 859

